<?php
namespace App\Http\Controllers;use App\Models\{Page,News,Event,Teacher,Program,Document};use Illuminate\Http\Request;class SearchController extends Controller{public function __invoke(Request $r){$q=trim((string)$r->query('q'));$results=collect();if(mb_strlen($q)>=2){$like='%'.$q.'%';Page::where('is_published',true)->where(fn($x)=>$x->where('title','like',$like)->orWhere('content','like',$like))->limit(12)->get()->each(fn($x)=>$results->push(['type'=>'Страница','title'=>$x->title,'text'=>$x->excerpt,'url'=>route('page.show',$x)]));News::where('is_published',true)->where(fn($x)=>$x->where('title','like',$like)->orWhere('content','like',$like))->limit(12)->get()->each(fn($x)=>$results->push(['type'=>'Новость','title'=>$x->title,'text'=>$x->excerpt,'url'=>route('news.show',$x)]));Teacher::where('is_active',true)->where('name','like',$like)->limit(12)->get()->each(fn($x)=>$results->push(['type'=>'Преподаватель','title'=>$x->name,'text'=>$x->position,'url'=>route('teachers.show',$x)]));Program::where('is_active',true)->where(fn($x)=>$x->where('name','like',$like)->orWhere('description','like',$like))->limit(12)->get()->each(fn($x)=>$results->push(['type'=>'Программа','title'=>$x->name,'text'=>$x->description,'url'=>route('programs.show',$x)]));Document::where('is_published',true)->where('title','like',$like)->limit(12)->get()->each(fn($x)=>$results->push(['type'=>'Документ','title'=>$x->title,'text'=>$x->category,'url'=>asset('storage/'.$x->file)]));}return view('search.index',compact('q','results'));}}